-- Nhà thuốc Minh An. Run once in the Supabase SQL Editor or via Supabase migrations.
-- The application accesses this schema through PostgreSQL, outside the public Data API.
BEGIN;
CREATE SCHEMA IF NOT EXISTS minhan;
REVOKE ALL ON SCHEMA minhan FROM PUBLIC;
SET LOCAL search_path TO minhan, pg_catalog;
-- 34 bảng nghiệp vụ theo báo cáo; tên cột được ánh xạ sang English cho ứng dụng.

CREATE TABLE IF NOT EXISTS nguoi_dung (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name TEXT NOT NULL, email TEXT UNIQUE, phone TEXT UNIQUE, password_hash TEXT NOT NULL, active BIGINT NOT NULL DEFAULT 1, verified BIGINT NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'), updated_at TEXT, CHECK(email IS NOT NULL OR phone IS NOT NULL));
CREATE TABLE IF NOT EXISTS khach_hang (id BIGINT PRIMARY KEY REFERENCES nguoi_dung(id) ON DELETE CASCADE DEFERRABLE INITIALLY IMMEDIATE);
CREATE TABLE IF NOT EXISTS nhan_vien (id BIGINT PRIMARY KEY REFERENCES nguoi_dung(id) ON DELETE CASCADE DEFERRABLE INITIALLY IMMEDIATE, job_title TEXT NOT NULL DEFAULT 'sales' CHECK(job_title IN ('pharmacist','sales','warehouse')));
CREATE TABLE IF NOT EXISTS quan_tri_vien (id BIGINT PRIMARY KEY REFERENCES nguoi_dung(id) ON DELETE CASCADE DEFERRABLE INITIALLY IMMEDIATE);
CREATE TABLE IF NOT EXISTS vai_tro (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name TEXT NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS nguoi_dung_vai_tro (user_id BIGINT NOT NULL REFERENCES nguoi_dung(id) ON DELETE CASCADE DEFERRABLE INITIALLY IMMEDIATE, role_id BIGINT NOT NULL REFERENCES vai_tro(id) DEFERRABLE INITIALLY IMMEDIATE, PRIMARY KEY(user_id,role_id));
CREATE TABLE IF NOT EXISTS quyen (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code TEXT NOT NULL UNIQUE, name TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS quyen_vai_tro (role_id BIGINT NOT NULL REFERENCES vai_tro(id) DEFERRABLE INITIALLY IMMEDIATE, permission_id BIGINT NOT NULL REFERENCES quyen(id) DEFERRABLE INITIALLY IMMEDIATE, PRIMARY KEY(role_id,permission_id));
CREATE TABLE IF NOT EXISTS phan_quyen (user_id BIGINT NOT NULL REFERENCES nguoi_dung(id) ON DELETE CASCADE DEFERRABLE INITIALLY IMMEDIATE, permission_id BIGINT NOT NULL REFERENCES quyen(id) DEFERRABLE INITIALLY IMMEDIATE, allowed BIGINT NOT NULL, PRIMARY KEY(user_id,permission_id));
CREATE TABLE IF NOT EXISTS ma_otp (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id BIGINT NOT NULL REFERENCES nguoi_dung(id) ON DELETE CASCADE DEFERRABLE INITIALLY IMMEDIATE, code_hash TEXT NOT NULL, purpose TEXT NOT NULL, expires_at TEXT NOT NULL, attempts BIGINT NOT NULL DEFAULT 0, consumed BIGINT NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'));
CREATE TABLE IF NOT EXISTS nhat_ky_hoat_dong (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id BIGINT REFERENCES nguoi_dung(id) DEFERRABLE INITIALLY IMMEDIATE, action TEXT NOT NULL, entity TEXT, entity_id TEXT, detail TEXT, created_at TEXT NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'));
CREATE TABLE IF NOT EXISTS danh_muc (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name TEXT NOT NULL UNIQUE, slug TEXT NOT NULL UNIQUE, description TEXT NOT NULL DEFAULT '', active BIGINT NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS nha_san_xuat (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name TEXT NOT NULL UNIQUE, country TEXT NOT NULL DEFAULT 'Việt Nam', active BIGINT NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS thuoc (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, category_id BIGINT NOT NULL REFERENCES danh_muc(id) DEFERRABLE INITIALLY IMMEDIATE, manufacturer_id BIGINT REFERENCES nha_san_xuat(id) DEFERRABLE INITIALLY IMMEDIATE, name TEXT NOT NULL, slug TEXT NOT NULL UNIQUE, ingredient TEXT NOT NULL DEFAULT '', description TEXT NOT NULL DEFAULT '', usage TEXT NOT NULL DEFAULT '', warning TEXT NOT NULL DEFAULT '', unit TEXT NOT NULL, price BIGINT NOT NULL CHECK(price>=0), old_price BIGINT, image TEXT NOT NULL DEFAULT '', prescription_required BIGINT NOT NULL DEFAULT 0, featured BIGINT NOT NULL DEFAULT 0, active BIGINT NOT NULL DEFAULT 1, created_at TEXT NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'), updated_at TEXT);
CREATE TABLE IF NOT EXISTS dia_chi_giao_hang (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id BIGINT NOT NULL REFERENCES nguoi_dung(id) ON DELETE CASCADE DEFERRABLE INITIALLY IMMEDIATE, recipient TEXT NOT NULL, phone TEXT NOT NULL, line1 TEXT NOT NULL, ward TEXT NOT NULL DEFAULT '', district TEXT NOT NULL DEFAULT '', city TEXT NOT NULL, is_default BIGINT NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS gio_hang (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id BIGINT NOT NULL UNIQUE REFERENCES nguoi_dung(id) ON DELETE CASCADE DEFERRABLE INITIALLY IMMEDIATE, updated_at TEXT NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'));
CREATE TABLE IF NOT EXISTS chi_tiet_gio_hang (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, cart_id BIGINT NOT NULL REFERENCES gio_hang(id) ON DELETE CASCADE DEFERRABLE INITIALLY IMMEDIATE, product_id BIGINT NOT NULL REFERENCES thuoc(id) DEFERRABLE INITIALLY IMMEDIATE, quantity BIGINT NOT NULL CHECK(quantity>0), UNIQUE(cart_id,product_id));
CREATE TABLE IF NOT EXISTS khuyen_mai (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code TEXT NOT NULL UNIQUE, name TEXT NOT NULL, type TEXT NOT NULL CHECK(type IN ('percent','fixed')), value BIGINT NOT NULL CHECK(value>0), min_order BIGINT NOT NULL DEFAULT 0, max_discount BIGINT, usage_limit BIGINT NOT NULL DEFAULT 100, used_count BIGINT NOT NULL DEFAULT 0, start_date TEXT NOT NULL, end_date TEXT NOT NULL, active BIGINT NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS don_hang (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id BIGINT NOT NULL REFERENCES nguoi_dung(id) DEFERRABLE INITIALLY IMMEDIATE, code TEXT NOT NULL UNIQUE, status TEXT NOT NULL, payment_method TEXT NOT NULL, payment_status TEXT NOT NULL DEFAULT 'unpaid', subtotal BIGINT NOT NULL, shipping_fee BIGINT NOT NULL, discount BIGINT NOT NULL DEFAULT 0, total BIGINT NOT NULL CHECK(total>=0), address_json TEXT NOT NULL, promotion_id BIGINT REFERENCES khuyen_mai(id) DEFERRABLE INITIALLY IMMEDIATE, note TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'), updated_at TEXT, stock_deducted BIGINT NOT NULL DEFAULT 0, stock_released BIGINT NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS chi_tiet_don_hang (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, order_id BIGINT NOT NULL REFERENCES don_hang(id) DEFERRABLE INITIALLY IMMEDIATE, product_id BIGINT NOT NULL REFERENCES thuoc(id) DEFERRABLE INITIALLY IMMEDIATE, name TEXT NOT NULL, unit TEXT NOT NULL, image TEXT NOT NULL, price BIGINT NOT NULL, quantity BIGINT NOT NULL CHECK(quantity>0), prescription_required BIGINT NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS don_thuoc (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id BIGINT NOT NULL REFERENCES nguoi_dung(id) DEFERRABLE INITIALLY IMMEDIATE, order_id BIGINT UNIQUE REFERENCES don_hang(id) DEFERRABLE INITIALLY IMMEDIATE, file_name TEXT NOT NULL, storage_name TEXT NOT NULL, mime_type TEXT NOT NULL, size BIGINT NOT NULL, status TEXT NOT NULL DEFAULT 'pending', note TEXT NOT NULL DEFAULT '', approved_product_ids TEXT, reviewer_id BIGINT REFERENCES nguoi_dung(id) DEFERRABLE INITIALLY IMMEDIATE, reviewed_at TEXT, created_at TEXT NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'));
CREATE TABLE IF NOT EXISTS giao_dich_thanh_toan (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, order_id BIGINT NOT NULL REFERENCES don_hang(id) DEFERRABLE INITIALLY IMMEDIATE, reference TEXT NOT NULL UNIQUE, type TEXT NOT NULL, provider TEXT NOT NULL, amount BIGINT NOT NULL, status TEXT NOT NULL, provider_reference TEXT, expires_at TEXT, created_at TEXT NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'));
CREATE TABLE IF NOT EXISTS yeu_cau_huy_hoan (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, order_id BIGINT NOT NULL REFERENCES don_hang(id) DEFERRABLE INITIALLY IMMEDIATE, user_id BIGINT NOT NULL REFERENCES nguoi_dung(id) DEFERRABLE INITIALLY IMMEDIATE, type TEXT NOT NULL, reason TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending', reply TEXT NOT NULL DEFAULT '', refund_amount BIGINT, restock BIGINT NOT NULL DEFAULT 0, evidence_storage_name TEXT, evidence_mime_type TEXT, handler_id BIGINT REFERENCES nguoi_dung(id) DEFERRABLE INITIALLY IMMEDIATE, created_at TEXT NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'), updated_at TEXT);
CREATE TABLE IF NOT EXISTS danh_gia (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, order_id BIGINT NOT NULL REFERENCES don_hang(id) DEFERRABLE INITIALLY IMMEDIATE, product_id BIGINT NOT NULL REFERENCES thuoc(id) DEFERRABLE INITIALLY IMMEDIATE, user_id BIGINT NOT NULL REFERENCES nguoi_dung(id) DEFERRABLE INITIALLY IMMEDIATE, rating BIGINT NOT NULL CHECK(rating BETWEEN 1 AND 5), comment TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'), UNIQUE(order_id,product_id,user_id));
CREATE TABLE IF NOT EXISTS nha_cung_cap (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name TEXT NOT NULL UNIQUE, email TEXT NOT NULL DEFAULT '', phone TEXT NOT NULL DEFAULT '', address TEXT NOT NULL DEFAULT '', active BIGINT NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS phieu_nhap_kho (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code TEXT NOT NULL UNIQUE, supplier_id BIGINT REFERENCES nha_cung_cap(id) DEFERRABLE INITIALLY IMMEDIATE, user_id BIGINT NOT NULL REFERENCES nguoi_dung(id) DEFERRABLE INITIALLY IMMEDIATE, total BIGINT NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'));
CREATE TABLE IF NOT EXISTS lo_thuoc (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, product_id BIGINT NOT NULL REFERENCES thuoc(id) DEFERRABLE INITIALLY IMMEDIATE, receipt_id BIGINT REFERENCES phieu_nhap_kho(id) DEFERRABLE INITIALLY IMMEDIATE, batch_number TEXT NOT NULL, quantity BIGINT NOT NULL CHECK(quantity>=0), reserved BIGINT NOT NULL DEFAULT 0 CHECK(reserved>=0 AND reserved<=quantity), cost BIGINT NOT NULL DEFAULT 0 CHECK(cost>=0), manufactured_at TEXT NOT NULL, expires_at TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'), UNIQUE(product_id,batch_number));
CREATE TABLE IF NOT EXISTS lich_su_ton_kho (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, product_id BIGINT NOT NULL REFERENCES thuoc(id) DEFERRABLE INITIALLY IMMEDIATE, batch_id BIGINT NOT NULL REFERENCES lo_thuoc(id) DEFERRABLE INITIALLY IMMEDIATE, order_id BIGINT REFERENCES don_hang(id) DEFERRABLE INITIALLY IMMEDIATE, user_id BIGINT REFERENCES nguoi_dung(id) DEFERRABLE INITIALLY IMMEDIATE, type TEXT NOT NULL, quantity BIGINT NOT NULL, reason TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'));
CREATE TABLE IF NOT EXISTS cuoc_hoi_thoai (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id BIGINT NOT NULL REFERENCES nguoi_dung(id) DEFERRABLE INITIALLY IMMEDIATE, title TEXT NOT NULL DEFAULT 'Cuộc trò chuyện mới', status TEXT NOT NULL DEFAULT 'active', created_at TEXT NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'), updated_at TEXT NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'));
CREATE TABLE IF NOT EXISTS tin_nhan (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, session_id BIGINT NOT NULL REFERENCES cuoc_hoi_thoai(id) ON DELETE CASCADE DEFERRABLE INITIALLY IMMEDIATE, role TEXT NOT NULL, content TEXT NOT NULL, mode TEXT NOT NULL DEFAULT 'knowledge', created_at TEXT NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'));
CREATE TABLE IF NOT EXISTS yeu_cau_ho_tro (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, session_id BIGINT NOT NULL REFERENCES cuoc_hoi_thoai(id) DEFERRABLE INITIALLY IMMEDIATE, user_id BIGINT NOT NULL REFERENCES nguoi_dung(id) DEFERRABLE INITIALLY IMMEDIATE, message TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'pending', reply TEXT NOT NULL DEFAULT '', handler_id BIGINT REFERENCES nguoi_dung(id) DEFERRABLE INITIALLY IMMEDIATE, created_at TEXT NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'), updated_at TEXT);
CREATE TABLE IF NOT EXISTS tri_thuc_chatbot (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, title TEXT NOT NULL, keywords TEXT NOT NULL, content TEXT NOT NULL, source TEXT, reviewed_at TEXT, reviewed_by BIGINT REFERENCES nguoi_dung(id) DEFERRABLE INITIALLY IMMEDIATE, active BIGINT NOT NULL DEFAULT 1, created_at TEXT NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'));
CREATE TABLE IF NOT EXISTS quy_tac_an_toan (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name TEXT NOT NULL, pattern TEXT NOT NULL, response TEXT NOT NULL, active BIGINT NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS tu_khoa_canh_bao (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, rule_id BIGINT NOT NULL REFERENCES quy_tac_an_toan(id) DEFERRABLE INITIALLY IMMEDIATE, keyword TEXT NOT NULL);
-- Các bảng kỹ thuật lưu phiên, cấu hình, giữ chỗ tồn kho, lịch sử và liên kết Google.
CREATE TABLE IF NOT EXISTS sessions (token_hash TEXT PRIMARY KEY, user_id BIGINT NOT NULL REFERENCES nguoi_dung(id) ON DELETE CASCADE DEFERRABLE INITIALLY IMMEDIATE, expires_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS settings (key TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS stock_allocations (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, order_id BIGINT NOT NULL REFERENCES don_hang(id) DEFERRABLE INITIALLY IMMEDIATE, batch_id BIGINT NOT NULL REFERENCES lo_thuoc(id) DEFERRABLE INITIALLY IMMEDIATE, quantity BIGINT NOT NULL CHECK(quantity>0), UNIQUE(order_id,batch_id));
CREATE TABLE IF NOT EXISTS order_status_history (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, order_id BIGINT NOT NULL REFERENCES don_hang(id) DEFERRABLE INITIALLY IMMEDIATE, status TEXT NOT NULL, user_id BIGINT REFERENCES nguoi_dung(id) DEFERRABLE INITIALLY IMMEDIATE, note TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'));
CREATE TABLE IF NOT EXISTS google_accounts (subject TEXT PRIMARY KEY, user_id BIGINT NOT NULL UNIQUE REFERENCES nguoi_dung(id) ON DELETE CASCADE DEFERRABLE INITIALLY IMMEDIATE);
CREATE TABLE IF NOT EXISTS oauth_states (state_hash TEXT PRIMARY KEY, nonce TEXT NOT NULL, verifier TEXT NOT NULL, user_id BIGINT REFERENCES nguoi_dung(id) ON DELETE CASCADE DEFERRABLE INITIALLY IMMEDIATE, expires_at BIGINT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_order_user ON don_hang(user_id,created_at);
CREATE INDEX IF NOT EXISTS idx_batch_expiry ON lo_thuoc(product_id,expires_at);
CREATE INDEX IF NOT EXISTS idx_message_session ON tin_nhan(session_id,id);
CREATE INDEX IF NOT EXISTS idx_otp_user ON ma_otp(user_id,purpose,id);

CREATE TABLE IF NOT EXISTS upload_intents (
  id TEXT PRIMARY KEY,
  user_id BIGINT NOT NULL REFERENCES nguoi_dung(id) ON DELETE CASCADE,
  kind TEXT NOT NULL CHECK(kind IN ('prescription', 'return')),
  original_name TEXT NOT NULL,
  mime_type TEXT NOT NULL,
  size BIGINT NOT NULL CHECK(size BETWEEN 1 AND 5242880),
  expires_at TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_upload_intents_user ON upload_intents(user_id, expires_at);
CREATE UNIQUE INDEX IF NOT EXISTS idx_address_default ON dia_chi_giao_hang(user_id) WHERE is_default=1;
CREATE UNIQUE INDEX IF NOT EXISTS idx_single_refund ON giao_dich_thanh_toan(order_id) WHERE type='refund' AND status IN ('pending','success');
REVOKE ALL ON ALL TABLES IN SCHEMA minhan FROM PUBLIC;
COMMIT;
